// with_article loads each row's `article` (many_to_one `articles`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q CommentQuery) with_article(configure ...fn (ArticleQuery) ArticleQuery) CommentQuery {
	mut next := q
	next.with_article = true
	next.article_fns = configure
	return next
}

// with_author loads each row's `author` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q CommentQuery) with_author(configure ...fn (UserQuery) UserQuery) CommentQuery {
	mut next := q
	next.with_author = true
	next.author_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q CommentQuery) all() ![]CommentNode {
	client, span := q.graph.client.start_span(.ops, 'query comments', 'comments', 'all')
	defer {
		span.end()
	}
	result := CommentQuery{
		...q
		graph: Graph{
			client: client
		}
	}.all_untraced() or {
		vgraph.span_failed(span, err)
		return err
	}
	vgraph.span_rows(span, result.len)
	return result
}

// all_untraced is `all`, without its span.
fn (q CommentQuery) all_untraced() ![]CommentNode {
	rows := load.select_where[models.Comment](q.graph.client.conn, q.graph.client.prepare_query('comments', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q CommentQuery) first() !CommentNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'comments'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q CommentQuery) nodes(rows []models.Comment) ![]CommentNode {
	mut nodes := rows.map(CommentNode{
		graph:   q.graph
		comment: it
	})
	if q.with_article {
		found := q.load_article(rows, q.article_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.comment.id.str()] or { [] }
			if list.len > 0 {
				node.article = &ArticleNode{
					...list[0]
				}
			}
			node.loaded << 'article'
		}
	}
	if q.with_author {
		found := q.load_author(rows, q.author_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.comment.id.str()] or { [] }
			if list.len > 0 {
				node.author = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'author'
		}
	}
	return nodes
}

// load_article loads the `article` of `rows`, keyed by each row's key.
fn (q CommentQuery) load_article(rows []models.Comment, fns []fn (ArticleQuery) ArticleQuery) !map[string][]ArticleNode {
	client, span := q.graph.client.start_load_span(.ops, 'comments', 'article', rows.len)
	defer {
		span.end()
	}
	result := CommentQuery{
		...q
		graph: Graph{
			client: client
		}
	}.load_article_untraced(rows, fns) or {
		vgraph.span_failed(span, err)
		return err
	}
	return result
}

// load_article_untraced is `load_article`, without its span.
fn (q CommentQuery) load_article_untraced(rows []models.Comment, fns []fn (ArticleQuery) ArticleQuery) !map[string][]ArticleNode {
	mut sub := q.graph.articles()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.article_id.str()
	}
	targets := sub.nodes(load.select_in[models.Article](q.graph.client.conn, 'id',
		load.unique(keys),
		query: q.graph.client.prepare_edge_query('articles', sub.query)!
	)!)!
	mut by_key := map[string]ArticleNode{}
	for target in targets {
		by_key[target.article.id.str()] = target
	}
	mut found := map[string][]ArticleNode{}
	for row in rows {
		if target := by_key[row.article_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// article_or_err returns the `article`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n CommentNode) article_or_err() !&ArticleNode {
	if 'article' !in n.loaded {
		return NotLoadedError{
			edge: 'comments.article'
		}
	}
	if target := n.article {
		return target
	}
	return NotFoundError{
		table: 'articles'
	}
}

// load_author loads the `author` of `rows`, keyed by each row's key.
fn (q CommentQuery) load_author(rows []models.Comment, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	client, span := q.graph.client.start_load_span(.ops, 'comments', 'author', rows.len)
	defer {
		span.end()
	}
	result := CommentQuery{
		...q
		graph: Graph{
			client: client
		}
	}.load_author_untraced(rows, fns) or {
		vgraph.span_failed(span, err)
		return err
